# ---- Perspective Custom Method: RecopileVars4Pens ----
# Where to place: on the parent "Linea X" Flex container.
# Returns: JSON string with the same structure as pensObject.json
"""
Build a JSON by scanning child 'formulary' containers and their
'Pen List' flex-repeater instances.

Path schema:
  [UNS]Clarios/Andina/{area_name}/{line_name}/Edge/{formulary_name}/{variable_name}

area_name  -> self.view.custom.area_name
line_name  -> prefer this container's meta.name if available; else fallback to a custom property 'line_name'
formulary  -> container label text (e.g., 'EA11-0901') or its meta.name
var name   -> read from the 'Pen List'.custom.instances[i].name
"""
import json

# ---------- 0) Helpers ----------
def _safe(d, key, default=None):
	try:
		return d.get(key, default)
	except:
		return default

def _get_child_by_name(comp, child_name):
	# Perspective exposes children via self.getChildren()
	for ch in comp.getChildren():
		try:
			# Designer "name" shows as ch.meta.name in JSON, but at runtime not always exposed.
			# Reliable fallback: compare the label child, or match by props if needed.
			if getattr(ch, "meta", None) and getattr(ch.meta, "name", None) == child_name:
				return ch
		except:
			pass
		# Fallback: match by props.meta.name if present
		try:
			if hasattr(ch.props, "meta") and hasattr(ch.props.meta, "name") and ch.props.meta.name == child_name:
				return ch
		except:
			pass
		# Last resort: if the child has a Label whose text equals the target name, treat as match
		try:
			for gch in ch.getChildren():
				if hasattr(gch.props, "text") and gch.props.text == child_name:
					return ch
		except:
			pass
	return None

def _find_label_text(comp):
	# Many formulary containers have a first child Label with the text equal to the formulary name.
	for ch in comp.getChildren():
		try:
			if hasattr(ch.props, "text") and ch.props.text:
				return ch.props.text
		except:
			pass
	return None

def _find_pen_list(comp):
	# Find the child flex-repeater named "Pen List"
	for ch in comp.getChildren():
		try:
			# Prefer meta.name == "Pen List"
			if getattr(ch, "meta", None) and getattr(ch.meta, "name", None) == "Pen List":
				return ch
		except:
			pass
		try:
			if hasattr(ch.props, "meta") and hasattr(ch.props.meta, "name") and ch.props.meta.name == "Pen List":
				return ch
		except:
			pass
		# Fallback: look for a flex-repeater component type by props.path commonly used in your layout
		try:
			if hasattr(ch.props, "path") and "Framework/Pen" in str(ch.props.path):
				return ch
		except:
			pass
	return None

def _pen_template(pen_name, source_path):
	# Minimal template aligned with pensObject.json fields
	# (keeps structure stable while letting Trend control colors/styles)
	return {
		"axis": "default",
		"data": {
			"aggregateMode": "default",
			"source": source_path
		},
		"display": {
			"breakLine": True,
			"interpolation": "curveLinear",
			"radius": 3,
			"styles": {
				"highlighted": {
					"fill":   {"color": "#888888", "opacity": 1},
					"stroke": {"color": "#888888", "dashArray": 0, "opacity": 1, "width": 1}
				},
				"muted": {
					"fill":   {"color": "#888888", "opacity": 0.4},
					"stroke": {"color": "#888888", "dashArray": 0, "opacity": 0.4, "width": 1}
				},
				"normal": {
					"fill":   {"color": "#888888", "opacity": 0.8},
					"stroke": {"color": "#888888", "dashArray": 0, "opacity": 0.8, "width": 1}
				},
				"selected": {
					"fill":   {"color": "#888888", "opacity": 1},
					"stroke": {"color": "#888888", "dashArray": 0, "opacity": 1, "width": 1}
				}
			},
			"type": "line"
		},
		"enabled": True,
		"name": pen_name,
		"plot": 1,
		"selectable": False,
		"visible": True
	}

# ---------- 1) Inputs from view ----------
area_name = _safe(self.view.custom, "area_name", "Area")

# Try to obtain the line name (parent container's "Linea X").
# Not all runtime contexts expose meta.name; allow a custom fallback.
line_name = None
try:
	# If you created a custom prop, this wins.
	line_name = getattr(self.custom, "line_name", None)
except:
	pass
if not line_name:
	# As a safe default, pull it from any child 'group' like "EA11-0901-Linea 1" if found.
	try:
		for c in self.getChildren():
			penList = _find_pen_list(c)
			if penList and hasattr(penList.custom, "instances"):
				insts = list(penList.custom.instances) if penList.custom.instances else []
				if insts:
					group = _safe(insts[0], "group", "")
					if "-" in group:
						line_name = group.split("-")[-1]
						break
	except:
		pass
if not line_name:
	line_name = "Linea 1"

# ---------- 2) Walk each 'formulary' container under this parent ----------
pens = []
for formulary in self.getChildren():
	try:
		# Get formulary_name from its Label text or (if available) meta.name.
		formulary_name = _find_label_text(formulary)
		if not formulary_name:
			try:
				formulary_name = formulary.meta.name
			except:
				pass
		if not formulary_name:
			# Not a formulary-like child; skip
			continue

		penList = _find_pen_list(formulary)
		if not penList or not hasattr(penList, "custom") or not hasattr(penList.custom, "instances"):
			# No 'Pen List' or no instances; skip
			continue

		instances = list(penList.custom.instances) if penList.custom.instances else []
		for inst in instances:
			var_name = _safe(inst, "name")
			if not var_name:
				continue
			source_path = "[UNS]Clarios/Andina/{}/{}/Edge/{}/{}".format(area_name, line_name, formulary_name, var_name)
			pens.append(_pen_template(var_name, source_path))
	except:
		# Continue even if one child is malformed
		continue

# ---------- 3) Return as JSON string ----------
logging.log("Finished Recopile Custom Method", "warn")
return pens

onChange.script:
config = currentValue.value

if config['mode'].value == 'historical':
	if previousValue != None:
		if previousValue.value != None:
			startDate = config['startDate'].value
			endDate = config['endDate'].value		

			daysBetween = system.date.daysBetween(startDate,endDate)

			if daysBetween > 14:
				oldStartDate = previousValue.value['startDate'].value
				oldEndDate = previousValue.value['endDate'].value

				if oldStartDate == startDate:
					self.props.config.startDate = system.date.addDays(endDate,-14)
				else:
					self.props.config.endDate = system.date.addDays(startDate,14)
elif config['mode'].value == 'realtime':
	units = config['measureOfTime'].value
	time = config['unitOfTime'].value

	if units == 'seconds':
		if time > 1209600:
			self.props.config.unitOfTime = 1209600
	elif units == 'minutes':
		if time > 20160:
			self.props.config.unitOfTime = 20160
	elif units == 'hours':
		if time > 336:
			self.props.config.unitOfTime = 336
	elif units == 'days':
		if time > 14:
			self.props.config.unitOfTime = 14
	elif units == 'weeks':
		if time > 2:
			self.props.config.unitOfTime = 2
	else:
		self.props.config.unitOfTime = 2
		self.props.config.measureOfTime = 'weeks'

